import{_ as t,o,c as a,af as n}from"./chunks/framework.BSym9njW.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"01-deploy/qwen36/qwen36_model.md","filePath":"en/01-deploy/qwen36/qwen36_model.md","lastUpdated":1789635951000}'),l={name:"01-deploy/qwen36/qwen36_model.md"};function d(r,e,s,i,p,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h2 id="qwen3-6-35b-a3b" tabindex="-1">Qwen3.6-35B-A3B <a class="header-anchor" href="#qwen3-6-35b-a3b" aria-label="Permalink to &quot;Qwen3.6-35B-A3B&quot;">​</a></h2><p>Qwen3.6-35B-A3B is a Qwen MoE text model (~<strong>35B total / 3B active</strong>). This chapter has two hardware paths: Lemonade / llama.cpp on <strong>GGUF + iGPU</strong>, FastFlowLM on <strong>NPU2 + XDNA2</strong>. Do not feed GGUF to <code>flm</code>, or <code>model.q4nx</code> to llama.cpp.</p><blockquote><p>GPU tutorials for earlier Qwen generations: <a href="/hello-rocm/01-deploy/qwen3/llamacpp-rocm7-deploy">Qwen3</a> · <a href="/hello-rocm/01-deploy/qwen3.5/llamacpp-rocm7-deploy">Qwen3.5</a>. A Lemonade id like <code>Qwen3.5-35B-A3B-GGUF</code> is a different generation — use an id that contains <strong>3.6</strong>.</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">Path</th><th style="text-align:left;">Format</th><th style="text-align:left;">Typical size</th><th style="text-align:left;">Runtime</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>GPU / Lemonade</strong></td><td style="text-align:left;">GGUF (<code>Qwen3.6-35B-A3B-GGUF</code>, often UD-Q4)</td><td style="text-align:left;">~20–23 GiB</td><td style="text-align:left;">Lemonade <code>llamacpp:vulkan</code> (or <code>rocm</code>) @ <strong>13305</strong></td></tr><tr><td style="text-align:left;"><strong>NPU / FastFlowLM</strong></td><td style="text-align:left;">NPU2</td><td style="text-align:left;">~<strong>29 GiB</strong> resident</td><td style="text-align:left;"><code>flm serve qwen3.6-moe:35b-a3b</code> @ <strong>8219</strong></td></tr></tbody></table><p>This is hungrier than Gemma 4 E4B (~9 GiB). Stop other large models first. On the validation host, NPU short-prompt concurrency 1/2/4/8 passed; long-form decode was about <strong>14 tok/s</strong>.</p><p>Deploy: <a href="./fastflowlm-npu-deploy">FastFlowLM NPU</a> · <a href="./lemonade-gpu-deploy">Lemonade GPU</a> · <a href="./lemonade-npu-deploy">Lemonade NPU</a></p>',6)])])}const f=t(l,[["render",d]]);export{g as __pageData,f as default};
